    if r and r:IsA("RemoteEvent") then track(r.OnClientEvent:Connect(function(a) if a == "Cap" then F.gemCap = true LOG("gem cap") end end)) end
end
F.drillNext = 0
S.onMsg = function(a, b)
    if type(b) ~= "string" then return end
    local t = b:lower()
    if t:find("drill is already") then F.drillNext = os.clock() + 25 end
    if t:find("sneaking") then F.stand = nil F.sneaks = (F.sneaks or 0) + 1 LOG("sent back, path rebuilt") end
end
function F.drillOk()
    if os.clock() < F.drillNext or Workspace:GetAttribute("DrillActive") == true then return false end
    if (Workspace:GetAttribute("DrillReadyAt") or 0) > Workspace:GetServerTimeNow() then return false end
    if lp:GetAttribute("Carrying") then return false end
    local lv = (D.Cfg and D.Cfg.stat and gcall(D.Cfg.stat, lp, "Drill")) or 0
    return type(lv) == "number" and lv > 0
end
function F.digStep()
    local r0 = M.root()
    if not r0 then return end
    if F.full() then S.task = on("f_sell") and __T["Selling soon"] or __T["Backpack full"] F.stuck = 0 task.wait(0.5) return end
    if not F.headY then
        local h = M.hum()
        if not h or h.FloorMaterial == Enum.Material.Air then task.wait(0.2) return end
        F.headY = r0.Position.Y + 1.5
    end
    local ez = F.exitZone()
    local order = F.order()
    local name = ez and "Exit" or order[F.wall]
    if not name then
        S.task = __T["Searched every wall"]
        F.wall, F.wp, F.stand = 1, 1, nil
        task.wait(1)
        return
    end
    local half = F.geom()
    local W, n
    if ez then
        local e = ez.Position
        n = math.abs(e.X) > math.abs(e.Z) and Vector3.new(math.sign(e.X), 0, 0) or Vector3.new(0, 0, math.sign(e.Z))
        local lat = Vector3.new(math.abs(n.Z), 0, math.abs(n.X))
        local side = (F.jig or 0) % 3 - 1
        W = Vector3.new(e.X, F.headY - 0.4, e.Z) + lat * side * 0.7
        if not F.exitMode then
            F.exitMode, F.stand, F.stuck = true, nil, 0
            LOG("exit route", tostring(e))
        end
        if not F.stand then
            local s = n * (half - 1.6) + Vector3.new(0, F.headY - 1.5, 0)
            F.stand = Vector3.new(n.X ~= 0 and s.X or math.clamp(e.X, -half + 1.4, half - 1.4), s.Y, n.Z ~= 0 and s.Z or math.clamp(e.Z, -half + 1.4, half - 1.4))
            F.trail = { F.stand }
        end
        local rr = M.root()
        local fe = Vector3.new(e.X, rr.Position.Y, e.Z) - rr.Position
        if fe.Magnitude < 12 then
            local clear = true
            for _, dy in ipairs({ 1.5, 0, -1.4 }) do
                if Workspace:Raycast(rr.Position + Vector3.new(0, dy, 0), fe, F.params()) then clear = false break end
            end
            if clear then
                S.task = __T["Walking out"]
                local h = M.hum()
                if h then h:MoveTo(e) end
                task.wait(0.4)
                return
            end
        end
    else
        F.exitMode = false
        local wps = F.waypoints(name)
        W = wps[F.wp]
        if not W then F.wall += 1 F.wp = 1 F.stand = nil return end
        n = F.DIRS[name]
        if not F.stand then F.stand = n * (half - 1.6) + Vector3.new(math.abs(n.Z), 0, math.abs(n.X)) * 0.13 + Vector3.new(0, F.headY - 1.5, 0) F.trail = { F.stand } end
    end
    pcall(F.goIn)
    local gp = (not ez and on("f_gems")) and F.gem(F.stand) or nil
    if gp then
        W = gp.Position
        local gk = F.gemKey(gp)
        if F.gemPart ~= gk then F.gemPart, F.gemAt = gk, os.clock() end
        if os.clock() - F.gemAt > 40 then F.gemSkip[gk] = os.clock() + 300 F.gemPart = nil LOG("gem skipped", gk) return end
        if (W - (F.stand + Vector3.new(0, 1.5, 0))).Magnitude < 0.6 then F.gemSkip[gk] = os.clock() + 300 return end
    end
    local head = F.stand + Vector3.new(0, 1.5, 0)
    local vec = W - head
    local dist = vec.Magnitude
    if dist < 0.6 then if not gp and not ez then F.wp += 1 end F.stuck = 0 return end
    F.anchor(false)
    local fl = Vector3.new(vec.X, 0, vec.Z)
    M.tp(CFrame.lookAt(F.stand, F.stand + (fl.Magnitude > 0.05 and fl or Vector3.new(0, 0, -1))))
    local r = Workspace:Raycast(head, vec.Unit * math.min(dist, 5.5), F.params())
    local flat = Vector3.new(vec.X, 0, vec.Z)
    local adv = 0
    if not r and flat.Magnitude > 0.3 then
        local fw = flat.Unit
        local block
        local s = 0.5
        while s <= math.min(flat.Magnitude, 2.5) + 0.01 do
            local parts = F.overlap(F.stand + fw * s, fw)
            if #parts > 0 then block = parts break end
            adv = s
            s += 0.5
        end
        if block and adv == 0 then
            table.sort(block, function(a, b) return (a.Position - head).Magnitude < (b.Position - head).Magnitude end)
            for n = 1, math.min(#block, 6) do
                local tp = block[n].Position
                local dv = tp - head
                local rb = Workspace:Raycast(head, dv.Unit * math.min(dv.Magnitude + 0.4, 5.5), F.params())
                if rb then r = rb break end
            end
        end
    end
    if r then
        S.task = ez and __T["Digging to the exit"] or (gp and __T["Digging to a gem"] or (__T["Digging "] .. name))
        local i, j, k, ax, su, sv = F.argsFor(r)
        local key = i .. "," .. j .. "," .. k
        if key == F.lastCell then F.stuck += 1 else F.stuck = 0 F.lastCell = key end
        if F.stuck > 30 then
            LOG("stuck at", key, "skipping waypoint")
            if ez then F.jig = (F.jig or 0) + 1
            elseif gp then F.gemSkip[F.gemKey(gp)] = os.clock() + 300 else F.wp += 1 end
            F.stuck = 0
            return
        end
        local q = math.floor(F.stuck / 8) % 4
        if q == 1 then su = -su elseif q == 2 then sv = -sv elseif q == 3 then su, sv = -su, -sv end
        M.fire("Dig", i, j, k, ax, su, sv)
        S.hits += 1
        if on("f_drill") and F.drillOk() and ax ~= 3 and ax ~= 4 then
            F.drillNext = os.clock() + 8
            M.fire("UseDrill", i, j, k, ax)
            LOG("drill placed", key)
        end
        task.wait(F.cooldown())
    else
        if flat.Magnitude < 0.6 then F.stuck = 0 if ez then return elseif gp then F.gemSkip[F.gemKey(gp)] = os.clock() + 300 else F.wp += 1 end return end
        if adv <= 0 then
            F.stuck += 1
            if F.stuck > 30 then
                LOG("path blocked, skipping")
                if ez then F.jig = (F.jig or 0) + 1 elseif gp then F.gemSkip[F.gemKey(gp)] = os.clock() + 300 else F.wp += 1 end
                F.stuck = 0
            end
            task.wait(0.1)
            return
        end
        F.stand = F.stand + flat.Unit * adv
        F.mark(F.stand)
    end
end
local U = { fails = {} }
function U.price(u, lvl)
    local c = u.costs and u.costs[lvl]
    if not c then return nil end
    local diff = Workspace:GetAttribute("Difficulty") or "Normal"
    local mult = D.Cfg and D.Cfg.PRICE_MULT and D.Cfg.PRICE_MULT[diff] or 1
    local rookie = Workspace:GetAttribute("RookiePrice")
    if type(rookie) == "number" and rookie > 0 and rookie < 1 then mult *= rookie end
    return c * mult
end
function U.level(u)
    local own = lp:GetAttribute("Lvl_" .. u.id)
    if type(own) == "number" then return own end
    local team = Workspace:GetAttribute("Team_" .. u.id)
    return type(team) == "number" and team or 1
end
function U.tick()
    if not (IS_MATCH and on("u_auto")) or not D.Cfg then return end
    local list = {}
    for _, u in ipairs(D.Cfg.UPGRADES or {}) do
        if not u.ping and picked("u_list", u.name or u.id) then
            local C = D.Cfg
            local lv = (C.level and gcall(C.level, lp, u.id)) or U.level(u)
            local maxed = type(u.values) == "table" and lv >= #u.values
            local open = true
            if C.unlocked then local ok = gcall(C.unlocked, lp, u) if ok == false then open = false end end
            local p = (not maxed and open) and ((C.cost and gcall(C.cost, u, lv)) or U.price(u, lv)) or nil
            if p and not (U.fails[u.id] and os.clock() < U.fails[u.id]) then list[#list + 1] = { u = u, p = p, lv = lv } end
        end
    end
    table.sort(list, function(a, b) return a.p < b.p end)
    for _, e in ipairs(list) do
        if M.spendable() < e.p then return end
        local m0 = M.money()
        M.fire("Buy", e.u.id)
        task.wait(0.35)
        if M.money() < m0 then S.bought += 1 LOG("bought", e.u.id, e.lv + 1) else U.fails[e.u.id] = os.clock() + 30 LOG("buy refused", e.u.id, e.p) end
    end
end
function U.names()
    local out = {}
    for _, u in ipairs((D.Cfg and D.Cfg.UPGRADES) or {}) do if not u.ping then out[#out + 1] = u.name or u.id end end
    return out
end
local LB = { codes = { "RELEASE", "1MVISITS", "YARDCREW" }, done = {} }
function LB.tick()
    if not IS_LOBBY then return end
    if on("l_codes") and not LB.codesDone then
        LB.codesDone = true
        for _, c in ipairs(LB.codes) do
            local ok, r = M.inv("Rewards", "code", c)
            LOG("code", c, ok, type(r) == "table" and (tostring(r.ok) .. " " .. tostring(r.msg or r.err or r.error)) or tostring(r))
            task.wait(1.5)
        end
    end
    if on("l_daily") and (not LB.dailyAt or os.clock() - LB.dailyAt > 120) then
        LB.dailyAt = os.clock()
        local ok, r = M.inv("Rewards", "daily")
        LOG("daily", ok, type(r) == "table" and tostring(r.ok) or tostring(r))
        local ok2, r2 = M.inv("Rewards", "community")
        LOG("community", ok2, type(r2) == "table" and tostring(r2.ok) or tostring(r2))
    end
    if on("l_free") and not LB.freeDone then
        LB.freeDone = true
        if M.remote("FavoriteReward") then LOG("fav", M.inv("FavoriteReward", "claim")) end
        if lp:GetAttribute("SorryGift") == true and M.remote("SorryGift") then LOG("sorry", M.inv("SorryGift", "claim")) end
        if M.remote("Pass") then LOG("pass", M.inv("Pass", "claimAll")) end
    end
    if on("l_quests") and (not LB.questAt or os.clock() - LB.questAt > 60) then
        LB.questAt = os.clock()
        local ok, st = M.inv("Rewards", "state")
        if ok and type(st) == "table" then
            for _, kind in ipairs({ "day", "week" }) do
                local qs = st.quests and st.quests[kind] or st[kind]
                for id, q in pairs(type(qs) == "table" and qs or {}) do
                    local qid = type(q) == "table" and (q.id or id) or id
                    local doneQ = type(q) == "table" and (q.done == true or q.complete == true or (q.progress and q.goal and q.progress >= q.goal)) and not q.claimed
                    if doneQ then local ok, r = M.inv("Rewards", "quest", kind, qid) LOG("quest", kind, qid, ok, type(r) == "table" and tostring(r.ok) or tostring(r)) task.wait(0.5) end
                end
            end
        end
    end
end
function LB.cfg()
    if LB.C == nil then
        local m = ReplicatedStorage:FindFirstChild("Lobby") and ReplicatedStorage.Lobby:FindFirstChild("Config")
        LB.C = (m and gcall(require, m)) or false
    end
    return LB.C or nil
end
function LB.start()
    if not (IS_LOBBY and on("l_start")) or (LB.startAt and os.clock() - LB.startAt < 12) then return end
    LB.startAt = os.clock()
    local rooms = Workspace:FindFirstChild("Lobby") and Workspace.Lobby:FindFirstChild("Rooms")
    local mine, free
    for _, r in ipairs(rooms and rooms:GetChildren() or {}) do
        if r:GetAttribute("Host") == lp.UserId then mine = r end
        if not free and r:GetAttribute("State") == "Idle" then free = r end
    end
    local room = mine or free
    if not room then LOG("no free room") return end
    if not mine then
        S.task = __T["Joining a room"]
        local pad = room:FindFirstChild("Pad") or room:FindFirstChild("Inside")
        local t = os.clock()
        while os.clock() - t < 6 and room:GetAttribute("Host") ~= lp.UserId do
            if pad then M.tp(CFrame.new(pad.Position + Vector3.new(0, 3, 0))) else M.tp(room:GetPivot() + Vector3.new(0, 3, 0)) end
            task.wait(0.4)
        end
    end
    if room:GetAttribute("Host") ~= lp.UserId then LOG("not host of", room.Name) return end
    local LC = LB.cfg()
    local priv = "Friends"
    if LC and type(LC.PRIVACY) == "table" then
        priv = LC.PRIVACY[#LC.PRIVACY] and LC.PRIVACY[#LC.PRIVACY].id or priv
        for _, p in ipairs(LC.PRIVACY) do if tostring(p.id):lower():find("friend") or tostring(p.id):lower():find("priv") then priv = p.id end end
    end
    local cfg = { max = 1, privacy = priv, difficulty = val("l_diff", "Normal"), chapter = 1 }
    if val("l_save", "Continue") == "Continue" then cfg.resume = true else cfg.replace = true end
    M.fire("Action", "Configure", cfg)
    task.wait(0.8)
    M.fire("Action", "Start")
    LOG("start", room.Name, priv)
    local t2 = os.clock()
    while os.clock() - t2 < 5 and room:GetAttribute("State") == "Setup" do task.wait(0.3) end
    LOG("room state", tostring(room:GetAttribute("State")), "max", tostring(room:GetAttribute("Max")))
end
TP = {}
function TP.hideVm(m, hide)
    if m.Name ~= "Viewmodel" then return end
    for _, d in ipairs(m:GetDescendants()) do
        if d:IsA("BasePart") then d.LocalTransparencyModifier = hide and 1 or 0
        elseif d:IsA("ParticleEmitter") or d:IsA("Beam") or d:IsA("Trail") then d.Enabled = not hide end
    end
end
function TP.apply()
    if not TP.on or lp:GetAttribute("Cinematic") == true or lp:GetAttribute("LuckyScene") == true then return end
    TP.minWas = TP.minWas or lp.CameraMinZoomDistance
    if lp.CameraMode ~= Enum.CameraMode.Classic then lp.CameraMode = Enum.CameraMode.Classic end
    TP.maxWas = TP.maxWas or lp.CameraMaxZoomDistance
    lp.CameraMaxZoomDistance = math.max(lp.CameraMaxZoomDistance, 60)
    lp.CameraMinZoomDistance = math.clamp(val("pl_zoom", 12), 4, 60)
end
function TP.set(v)
    TP.on = v
    local cam = Workspace.CurrentCamera
    if TP.conn then TP.conn:Disconnect() TP.conn = nil end
    if v then
        TP.apply()
        if cam then
            for _, m in ipairs(cam:GetChildren()) do TP.hideVm(m, true) end
            TP.conn = cam.ChildAdded:Connect(function(m) task.defer(function() if TP.on then TP.hideVm(m, true) end end) end)
        end
    else
        if cam then for _, m in ipairs(cam:GetChildren()) do TP.hideVm(m, false) end end
        lp.CameraMinZoomDistance = TP.minWas or 0.5
        if TP.maxWas then lp.CameraMaxZoomDistance = TP.maxWas end
        TP.minWas, TP.maxWas = nil, nil
        if IS_MATCH and lp:GetAttribute("Cinematic") ~= true then lp.CameraMode = Enum.CameraMode.LockFirstPerson end
    end
end
track(lp:GetPropertyChangedSignal("CameraMode"):Connect(function() if TP.on then TP.apply() end end))
track(lp:GetAttributeChangedSignal("Cinematic"):Connect(function() task.defer(function() if TP.on then TP.apply() end end) end))
track(lp.CharacterAdded:Connect(function() task.defer(function() if TP.on then TP.apply() end end) end))
track(RunService.RenderStepped:Connect(function()
    if not TP.on or FC.on or lp:GetAttribute("Cinematic") == true or lp:GetAttribute("LuckyScene") == true then return end
    if lp.CameraMode ~= Enum.CameraMode.Classic or lp.CameraMinZoomDistance < 3.9 then TP.apply() end
    local uis = game:GetService("UserInputService")
    if uis.MouseBehavior == Enum.MouseBehavior.LockCenter then uis.MouseBehavior = Enum.MouseBehavior.Default end
    if not uis.MouseIconEnabled then uis.MouseIconEnabled = true end
    local cam = Workspace.CurrentCamera
    local vm = cam and cam:FindFirstChild("Viewmodel")
    if vm then for _, d in ipairs(vm:GetChildren()) do if d:IsA("BasePart") and d.LocalTransparencyModifier ~= 1 then TP.hideVm(vm, true) break end end end
end))
onClean(function() if TP.on then pcall(TP.set, false) end end)
function TP.aim()
    local c = lp.Character
    local hd = c and c:FindFirstChild("Head")
    local cam = Workspace.CurrentCamera
    if not (hd and cam and D.Grid) then return end
    local uis = game:GetService("UserInputService")
    local mp = uis:GetMouseLocation()
    local ray = cam:ViewportPointToRay(mp.X, mp.Y)
    local far = Workspace:Raycast(ray.Origin, ray.Direction * 200, F.params())
    local target = far and far.Position or (ray.Origin + ray.Direction * 30)
    local dir = target - hd.Position
    if dir.Magnitude < 0.05 then return end
    local reach = (D.Cfg and D.Cfg.REACH) or 7
    return Workspace:Raycast(hd.Position, dir.Unit * (reach - 0.3), F.params())
end
FC = {}
function FC.showBody()
    local c = lp.Character
    if not c then return end
    for _, p in ipairs(c:GetDescendants()) do
        if p:IsA("BasePart") and p.Name ~= "HumanoidRootPart" and p.LocalTransparencyModifier ~= 0 then p.LocalTransparencyModifier = 0 end
    end
end
function FC.set(v)
    local cam = Workspace.CurrentCamera
    local cas = game:GetService("ContextActionService")
    local uis = game:GetService("UserInputService")
    if FC.step then FC.step:Disconnect() FC.step = nil end
    pcall(function() cas:UnbindAction("CW_PUNCH_FC") end)
    FC.on = v
    if not cam then return end
    if v then
        local _, yaw = cam.CFrame:ToEulerAnglesYXZ()
        local pitch = math.asin(math.clamp(cam.CFrame.LookVector.Y, -1, 1))
        FC.pos, FC.yaw, FC.pitch = cam.CFrame.Position, yaw, pitch
        cas:BindActionAtPriority("CW_PUNCH_FC", function() return Enum.ContextActionResult.Sink end, false, 3000,
            Enum.PlayerActions.CharacterForward, Enum.PlayerActions.CharacterBackward, Enum.PlayerActions.CharacterLeft,
            Enum.PlayerActions.CharacterRight, Enum.PlayerActions.CharacterJump, Enum.KeyCode.W, Enum.KeyCode.A,
            Enum.KeyCode.S, Enum.KeyCode.D, Enum.KeyCode.Space, Enum.KeyCode.Q, Enum.KeyCode.E)
        FC.step = RunService.RenderStepped:Connect(function(dt)
            if cam ~= Workspace.CurrentCamera then cam = Workspace.CurrentCamera end
            if cam.CameraType ~= Enum.CameraType.Scriptable then cam.CameraType = Enum.CameraType.Scriptable end
            if uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                uis.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
                local md = uis:GetMouseDelta()
                FC.yaw -= md.X * 0.004
                FC.pitch = math.clamp(FC.pitch - md.Y * 0.004, -1.5, 1.5)
            else
                uis.MouseBehavior = Enum.MouseBehavior.Default
            end
            uis.MouseIconEnabled = true
            local rot = CFrame.fromEulerAnglesYXZ(FC.pitch, FC.yaw, 0)
            local mv = Vector3.zero
            local function k(c) return uis:IsKeyDown(c) and not uis:GetFocusedTextBox() end
            if k(Enum.KeyCode.W) then mv += Vector3.new(0, 0, -1) end
            if k(Enum.KeyCode.S) then mv += Vector3.new(0, 0, 1) end
            if k(Enum.KeyCode.A) then mv += Vector3.new(-1, 0, 0) end
            if k(Enum.KeyCode.D) then mv += Vector3.new(1, 0, 0) end
            if k(Enum.KeyCode.E) or k(Enum.KeyCode.Space) then mv += Vector3.new(0, 1, 0) end
            if k(Enum.KeyCode.Q) then mv += Vector3.new(0, -1, 0) end
            local sp = (tonumber(val("pl_fc_speed", 30)) or 30) * (k(Enum.KeyCode.LeftShift) and 3 or 1)
            if mv.Magnitude > 0 then FC.pos += rot:VectorToWorldSpace(mv.Unit) * sp * dt end
            cam.CFrame = CFrame.new(FC.pos) * rot
            FC.showBody()
            for _, m in ipairs(cam:GetChildren()) do if m.Name == "Viewmodel" then TP.hideVm(m, true) end end
        end)
    else
        cam.CameraType = Enum.CameraType.Custom
        uis.MouseBehavior = Enum.MouseBehavior.Default
        if not TP.on then for _, m in ipairs(cam:GetChildren()) do TP.hideVm(m, false) end end
        local h = M.hum()
        if h then cam.CameraSubject = h end
    end
end
onClean(function() if FC.on then pcall(FC.set, false) end end)
function TP.manual() return TP.on and not FC.on and IS_MATCH and not (on("f_dig") and not on("f_pause")) and M.ready() end
do
    local uis = game:GetService("UserInputService")
    track(uis.InputBegan:Connect(function(io, gp)
        if gp or not TP.manual() then return end
        if io.KeyCode == Enum.KeyCode.F or io.KeyCode == Enum.KeyCode.ButtonL1 then
            local r = TP.aim()
            if not r then notify(__T["Aim at a wall"]) return end
            local i, j, k, ax = F.argsFor(r)
            if ax == 3 or ax == 4 then notify(__T["Aim at a wall"]) return end
            M.fire("UseDrill", i, j, k, ax)
        elseif io.UserInputType == Enum.UserInputType.MouseButton1 and not TP.punching then
            TP.punching = true
            task.spawn(function()
                while RUNNING and TP.manual() and uis:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
                    local r = TP.aim()
                    if r then
                        local i, j, k, ax, su, sv = F.argsFor(r)
                        M.fire("Dig", i, j, k, ax, su, sv)
                        S.hits += 1
                    end
                    task.wait(F.cooldown())
                end
                TP.punching = false
            end)
        end
    end))
end
